import { Component, inject, signal } from '@angular/core';

import { EventService } from '../../../core/services/event.service';
import { EventListItem } from '../../../core/models/event.model';
import { EventCard } from '../event-card/event-card';

@Component({
  selector: 'app-event-list-page',
  imports: [EventCard],
  templateUrl: './event-list-page.html',
  styleUrl: './event-list-page.scss'
})
export class EventListPage {
  private readonly eventService = inject(EventService);

  protected readonly events = signal<EventListItem[] | null>(null);
  protected readonly loadError = signal(false);
  protected readonly placeholderCount = 5;
  protected readonly placeholders = Array.from({ length: this.placeholderCount });

  constructor() {
    this.eventService.getEvents().subscribe({
      next: (events) => this.events.set(events),
      error: () => this.loadError.set(true)
    });
  }
}
--- event-list-page.html ---
<h1 class="event-list-page__heading">Programm</h1>

@if (loadError()) {
  <p class="event-list-page__error" role="alert">Veranstaltungen konnten nicht geladen werden.</p>
} @else if (events(); as loadedEvents) {
  <div class="event-list-page__grid">
    @for (event of loadedEvents; track event.id) {
      <app-event-card
        [id]="event.id"
        [title]="event.title"
        [venueName]="event.venueName"
        [startsAt]="event.startsAt"
      />
    }
  </div>
} @else {
  <div class="event-list-page__grid" aria-busy="true" aria-label="Veranstaltungen werden geladen">
    @for (placeholder of placeholders; track $index) {
      <div class="event-list-page__placeholder-card"></div>
    }
  </div>
}
